('bmlt-labquality1-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1,$json${"question":"Internal quality control (IQC) is primarily used to:","translation":"","options":["Monitor reliability of test performance within a laboratory","Replace external quality assessment","Diagnose every patient independently","Calibrate all instruments automatically"],"correctIndex":0,"explanation":"IQC monitors day-to-day analytical performance.","explanationNe":"IQC ले दैनिक analytical performance निगरानी गर्छ।","topic":"Laboratory Quality Assurance"}$json$::jsonb,true),
