('bmlt-labquality1-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',4,$json${"question":"The Westgard 1₃s rule is commonly interpreted as:","translation":"","options":["One control result exceeds ±3 SD; reject the run","Two results exceed ±1 SD; always accept","All controls are within mean","Calibration is unnecessary"],"correctIndex":0,"explanation":"A single control beyond 3 SD is a rejection signal.","explanationNe":"एक control result ±3 SD बाहिर भए run reject गर्ने संकेत हो।","topic":"Laboratory Quality Assurance"}$json$::jsonb,true),
('bmlt-labquality1-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',5,$json${"question":"The Westgard 2₂s rule suggests:","translation":"","options":["Two consecutive control results exceed the same ±2 SD limit","One result is exactly at mean","Two patient results are identical","Two instruments are required"],"correctIndex":0,"explanation":"2₂s may indicate systematic error and usually triggers rejection.","explanationNe":"2₂s systematic error को संकेत हुन सक्छ र run reject गर्नुपर्छ।","topic":"Laboratory Quality Assurance"}$json$::jsonb,true),
('bmlt-labquality1-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',6,$json${"question":"A systematic error typically causes:","translation":"","options":["Consistent bias in one direction","Random scatter only","No change in results","Only specimen mislabeling"],"correctIndex":0,"explanation":"Systematic error shifts results consistently from the target.","explanationNe":"Systematic error ले result लाई target बाट लगातार एक दिशामा सार्छ।","topic":"Laboratory Quality Assurance"}$json$::jsonb,true),
('bmlt-labquality1-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',7,$json${"question":"Random analytical error is characterized by:","translation":"","options":["Unpredictable variation around the target","A constant fixed bias only","A wrong reference interval only","A deliberate change in units"],"correctIndex":0,"explanation":"Random error increases imprecision and varies unpredictably.","explanationNe":"Random error ले imprecision बढाउँछ र अनियमित रूपमा बदलिन्छ।","topic":"Laboratory Quality Assurance"}$json$::jsonb,true),
